import numpy as np
from inertia import CONFIG, Plant, WaterModel
from inertia_ext import Sinks


class Report:
    def __init__(self, res, config=CONFIG):
        self.r, self.cfg = res, config
        self.W, self.B, self.T, self.D, self.S, self.ST, self.PH, self.E = (res[k] for k in ("water", "boot", "tables", "dynamics", "settings", "steptest", "physical", "ext"))
        self.x = dict(zip(self.W["names"], self.W["x"]))
        self.P = config["plant"]
        self.m = WaterModel(config)
        self.o = []

    def a(self, text=""):
        self.o.append(text)

    @staticmethod
    def tab(head, rows):
        return "\n".join(["| " + " | ".join(head) + " |", "|" + "---|" * len(head)] + ["| " + " | ".join(str(c) for c in r) + " |" for r in rows])

    @staticmethod
    def f(v, n=1):
        return "n/a" if v is None else f"{v:.{n}f}"

    def ci(self, d, n=1):
        return f"{d['p50']:.{n}f} [{d['p2_5']:.{n}f}, {d['p97_5']:.{n}f}]"

    def rate(self, model, q, gs):
        return next(r for r in self.E["rates"] if r["model"] == model and r["q_w"] == q and r["gs"] == gs)

    def stuck(self, model, variant, q, policy):
        return next(r for r in self.E["restart"]["stuck"] if r["model"] == model and r["variant"] == variant and r["q_w"] == q and r["policy"] == policy)

    def sink_rows(self):
        base = self.S["base"]
        g = {f"model G, pump floor ({base['G']['full_pump_floor']:.1f})": base["G"]["full_pump_floor"], "G 23.8 (pump 100 %)": 23.8, "G 22.3 (low end of the CI)": 22.3}
        return Sinks(np.array(self.W["x"]), self.m, self.cfg).table(g)

    def build(self):
        self.head()
        self.data()
        self.water()
        self.dynamics()
        self.identification()
        self.capacity()
        self.settings()
        self.final()
        self.limits()
        return "\n".join(self.o)

    def head(self):
        W, B, E, S, a, tab, x = self.W, self.B, self.E, self.S, self.a, self.tab, self.x
        f = self.f
        fz = E["frozen"]["cv"]
        ef = E["events"]["fit"]
        a("# Thermal inertia of the loop and settings derived from it\n")
        a("Generated by `python/inertia.py` (stages water, dynamics, settings, tables, ext, steptest, physical, bootstrap, report; `inertia_ext.py` holds the two-lump, event, frozen-power and restart analyses, `inertia_report.py` this text). Read-only analysis of the lake extract (Parquet copy); nothing was written to hardware, no device was opened, `src/` is unchanged. Every number below was measured or simulated by that script unless marked ESTIMATE. This version applies the corrections of the independent review (H1 to H3, M1 to M7, LOW).\n")
        a("Owner's limits used throughout: water plan limit 46 C, firmware takeover above 48 C, top limit 50 C; CPU and GPU temperatures never trigger anything; pump floor 15 %; fan stop 33 C, restart 35 C, start duty 20 %; decision 30 s, horizon 240 s.\n")
        a("## 0. Result in brief\n")
        pooled = W["cv"]["pooled"]
        pc = B["params"]["C"]
        cv_known = " / ".join(f"{pooled[h]['rmse_model']:.2f} vs {pooled[h]['rmse_persist']:.2f}" for h in ("300", "900", "1800"))
        cv_frozen = " / ".join(f"{fz[str(h)]['rmse_frozen']:.2f} vs {fz[str(h)]['rmse_persist']:.2f}" for h in (300, 900, 1800))
        rows = [
            ["Held-out days beat persistence at 5, 15, 30 min (power over the horizon known)", f"{cv_known} K (model vs persistence RMSE)", "PASS, but not a forecast test: the future power is an input"],
            ["Same test with power frozen at decision time (what a planner can do)", f"{cv_frozen} K; skill {' / '.join(f'{100 * fz[str(h)]['skill_frozen']:.0f} %' for h in (300, 900, 1800))}", "FAIL at every horizon: the model is worse than persistence"],
            ["Block-bootstrap interval on C within +-30 %", f"C = {pc['p50'] / 1000:.1f} kJ/K [{pc['p2_5'] / 1000:.1f}, {pc['p97_5'] / 1000:.1f}], half width {100 * B['C_half_width_rel']:.1f} % ({B['draws']} draws, {B['block_h']:g} h blocks)", "PASS" if B["pass_C_within_30pct"] else "FAIL"],
            ["Implied C plausible for 3 x 360 radiators plus coolant", f"{self.PH['fitted_kj_per_k']:.1f} kJ/K against ESTIMATE {self.PH['estimate_kj_per_k'][0]:.1f} to {self.PH['estimate_kj_per_k'][1]:.1f} kJ/K", "PASS, weak: the ESTIMATE range is wide and hard to miss"],
            ["Heat share reaching water", f"CPU {self.ci(B['params']['eta_cpu'], 2)}; GPU pinned at the cap 1.0", "PASS for CPU, GPU only bounded from below"],
            ["One lump after the dead time (earlier claim)", f"event-locked rise 0.69 / 0.74 K/min per 100 W over 30 to 60 s at pump 100 % / 20 % against 0.48 for one lump", "REFUTED for the first 4 min; two lumps needed (3.2)"],
        ]
        a(tab(["Fixed criterion", "Result", "Verdict"], rows))
        a("")
        base = S["base"]
        r4_05, r4_5 = self.rate("lump2", 400.0, 0.5), self.rate("lump2", 400.0, 5.0)
        r2_05 = self.rate("lump2", 200.0, 0.5)
        l1_4, l1_2 = self.rate("lump1", 400.0, 0.5), self.rate("lump1", 200.0, 0.5)
        lump = E["lump"]
        s23 = {r["sink_c"]: r for r in self.sink_rows() if r["g_label"].startswith("G 23.8")}
        a("Headline numbers:\n")
        a(f"- Total heat capacity C = {x['C'] / 1000:.1f} kJ/K (bootstrap {pc['p2_5'] / 1000:.1f} to {pc['p97_5'] / 1000:.1f}; structural variants {min(s['x'][0] for s in W['sensitivity']) / 1000:.1f} to {max(s['x'][0] for s in W['sensitivity']) / 1000:.1f}). It is not one lump: for the first 4 min the fast part is C1 = {lump['C1'] / 1000:.1f} kJ/K (event fits {min(v['C1'] for v in [ef] + list(E['events']['fit_variants'].values())) / 1000:.1f} to {max(v['C1'] for v in [ef] + list(E['events']['fit_variants'].values())) / 1000:.1f}) with fast tau {lump['tau_fast_s']:.0f} s (fits {min(v['tau_fast_s'] for v in [ef] + list(E['events']['fit_variants'].values())):.0f} to {max(v['tau_fast_s'] for v in [ef] + list(E['events']['fit_variants'].values())):.0f} s); the rest (C2 = {lump['C2'] / 1000:.1f} kJ/K) follows within minutes.")
        a(f"- Time constant tau = C/G at full fan: {self.ci(B['tau_full_pump100_s'], 0)} s with pump 100 %, {self.ci(B['tau_full_pump20_s'], 0)} s with pump about 20 %. The review's independent estimates of the slow tau spread over about 400 to 700 s (about 25 % around 480 s), wider than any interval shown here.")
        a(f"- G at full fan {self.ci(B['G_full_pump100'])} W/K (pump 100 %), {self.ci(B['G_full_pump20'])} W/K (pump about 20 %); 23.8 W/K is used for capacity, 22.3 W/K is the low end of the review's interval.")
        a(f"- Dead time from power to the water sensor: {S['dead_s']['100']:.0f} s at pump 100 % (centroid), {S['dead_s']['20']:.0f} s at pump about 20 % (event-locked fits {ef['delay_s']['p100']:.0f} / {ef['delay_s']['p20']:.0f} s); {S['dead_s']['floor_est']:.0f} s ESTIMATE at the 15 % floor. Onset of the first visible rise about {E['events']['p100']['onset_s']:.0f} s at pump 100 %.")
        a(f"- Heating rate with the fan stopped, 200 W: one lump {l1_2['avg_k_min_4min']:.1f} K/min, two lumps {r2_05['k_min_at_60s']:.1f} K/min at 60 s and {r2_05['avg_k_min_4min']:.1f} K/min over 4 min (G_stop 0.5 W/K; {self.rate('lump2', 200.0, 5.0)['avg_k_min_4min']:.1f} with 5 W/K). At 400 W: one lump {l1_4['avg_k_min_4min']:.1f}, two lumps {r4_05['k_min_at_60s']:.1f} K/min at 60 s, {r4_05['avg_k_min_4min']:.1f} over 4 min ({r4_5['avg_k_min_4min']:.1f} with 5 W/K), {r4_05['k_min_at_t0']:.1f} at the very start. The earlier 2.05 K/min at 400 W is the one-lump value and is too low for the first minutes.")
        a(f"- Capacity of the radiators at full fan, pump floor (G 23.8 W/K, ambient/sink assumed): at sink 25 C {s23[25.0]['cap_46_w']:.0f} W holds 46 C and {s23[25.0]['cap_50_w']:.0f} W holds 50 C; at sink 30 C {s23[30.0]['cap_46_w']:.0f} / {s23[30.0]['cap_50_w']:.0f} W; at sink 32 C {s23[32.0]['cap_46_w']:.0f} / {s23[32.0]['cap_50_w']:.0f} W. Each K of warmer sink costs about {23.8:.0f} W. The measured peak is CPU {E['peaks']['cpu_max_w']:.0f} W plus a GPU rated {self.cfg['ext']['sinks']['peak_gpu_rated_w']:.0f} W, about {E['peaks']['cpu_max_w'] + self.cfg['ext']['sinks']['peak_gpu_rated_w']:.0f} W. **At full fan nothing defends 50 C once the heat exceeds the capacity: the fan is already at its limit, the 48 C takeover adds nothing, the 50 C limit is an alarm.**")
        a(f"- Forecast margin with the future power unknown (frozen at decision time): RMSE {fz['240']['rmse_frozen']:.2f} / {fz['300']['rmse_frozen']:.2f} / {fz['480']['rmse_frozen']:.2f} / {fz['900']['rmse_frozen']:.2f} K at 240 / 300 / 480 / 900 s against persistence {fz['240']['rmse_persist']:.2f} / {fz['300']['rmse_persist']:.2f} / {fz['480']['rmse_persist']:.2f} / {fz['900']['rmse_persist']:.2f}; 2 sigma is {fz['240']['two_sigma']:.1f} to {fz['480']['two_sigma']:.1f} K (not 0.5 to 0.9 K), p99 under-prediction {fz['240']['p99_under']:.1f} to {fz['480']['p99_under']:.1f} K.")
        st = self.stuck("lump2", "nominal", 400.0, "stuck")
        ru = self.stuck("lump2", "nominal", 400.0, "rule")
        a(f"- Restart worst case: the stop/restart rule is safe only if the planner then drives the fan up. If the planner stays at the start duty ({E['restart']['min_run_rpm']:.0f} rpm), 400 W from a stop at 33 C reaches 46 C after {st['t_46_s']} s and 48 C after {st['t_48_s']} s (two lumps; one lump {self.stuck('lump1', 'nominal', 400.0, 'stuck')['t_46_s']} / {self.stuck('lump1', 'nominal', 400.0, 'stuck')['t_48_s']} s) and peaks at {st['peak_k']:.1f} C even though the firmware takes over at 48 C. A model-independent floor (35 C start duty, 38 C 800 rpm, 42 C full) holds the peak to {ru['peak_k']:.1f} C. With a dead daemon (fan 0, no restart) 400 W takes {self.daemon_range(400.0)} from 33 to 50 C.")
        a("- Not identifiable from the data: G below about 1100 rpm (P0 and C trade, 4.2), natural-convection G with the fan stopped, anything about the pump floor above 36 C (no data, 4.1), 8 of the 9 fans (one tach). All rpm figures end with the planned fan swap.\n")

    def daemon_range(self, q):
        rows = [r for r in self.E["restart"]["daemon"] if r["q_w"] == q and r["variant"] == "nominal"]
        v = [r["t_50_s"] for r in rows if r["t_50_s"]]
        return f"{min(v) / 60:.0f} to {max(v) / 60:.0f} min"

    def data(self):
        a, ex, cfg = self.a, self.T["exposure"], self.cfg
        a("## 1. Data used\n")
        a(f"- Lake span {ex['span_h']:.1f} h (2026-11-01 09:34 UTC to 11-05 ~07:00 UTC), {ex['hours']:.1f} h with D5 water, fan and pump channels, {ex['cpu_power_hours']:.1f} h with CPU power from LHM (the 11-03 session has none and is excluded from every power-dependent fit). Gaps longer than {cfg['gap_max']} s break segments; no fit or window crosses a gap (see `snapshot/crash-log.md` for the outages). Gaps up to {cfg['gap_max']} s are linearly filled.")
        a("- Channels: `d5next/water/temp`, `d5next/fan/rpm|duty|power`, `d5next/pump/rpm|duty|power`, `/intelcpu/0/power/0` (package), `/intelcpu/0/temperature/0|1` (core max, average), `nvml/0/power|temp`, `/gpu-nvidia/0/temperature/0|2|3`, `/usbhid/.../temperature/0` (LHM copy of the D5 water sensor).")
        a(f"- Ambient: there is no ambient or room sensor in the lake and the D5 virtual sensors are unassigned. Board System ({ex['sys_temp_range'][0]:.0f} to {ex['sys_temp_range'][1]:.0f} C) and other case sensors all read above the water floor ({ex['tw_min']:.1f} C), so none is an air-inlet proxy. The sink temperature Ta is an unknown parameter (16 to 29 C in the fit); only the intercept Ta + P0/G is identified (the review finds it constant at 24.1 to 25.5 C across all 6 h buckets, so no drift in this data).")
        a(f"- Exposure: water {ex['tw_p1']:.1f} to {ex['tw_p99']:.1f} C (1st to 99th percentile, max {ex['tw_max']:.1f}); fan at full speed {100 * ex['fan_full_fraction']:.0f} % of the time, below 70 % of full rpm for {ex['fan_below_0_7_hours']:.1f} h, below 40 % for {ex['fan_below_0_4_hours']:.2f} h (minimum {ex['fan_min_rpm']:.0f} rpm); pump 100 % for {ex['pump_hours']['100']:.1f} h, about 20 % (2570 rpm) for {ex['pump_hours']['20']:.1f} h, anything else {ex['pump_hours']['other']:.1f} h. Water above 42 C was never seen. Peak heat seen: {self.E['peaks']['q_max_w']:.0f} W (99.9th percentile {self.E['peaks']['q_p999_w']:.0f} W).")
        a("- Only one tach is read: 8 of the 9 fans are unobserved, and start-up at 20 % duty from standstill is unverified. All rpm figures in this document are for the current nine fans and end with the planned iCUE LINK swap (`snapshot/icue-link.md`).")
        a("- Extraction once to Parquet (`wide.parquet`, 1 s grid, 152 channels) by `Store.extract`; everything else reads that copy.\n")

    def water(self):
        a, tab, W, B, T, S, x, cfg, E = self.a, self.tab, self.W, self.B, self.T, self.S, self.x, self.cfg, self.E
        f = self.f
        pooled = W["cv"]["pooled"]
        fz = E["frozen"]["cv"]
        base, alt = S["base"], S["alt"]
        a("## 2. Water model\n")
        a("C dTw/dt = eta_cpu Pcpu + eta_gpu Pgpu + Ppump + P0 - G(fan, pump) (Tw - Ta), with G = Gn + A (rpm/1460)^m (1 + gamma (pump_rpm/4800 - 1)). Ppump is the measured D5 pump power, P0 is zero in the headline fit and free in the ambient profile. Fitted by multi-step output error on 30 min windows (30 s steps, exact exponential step, Levenberg-Marquardt). Only eta/G and eta/C are identified in absolute terms (the review finds eta about 0.8 and G 18.6 W/K if eta is free), so absolute C and G assume eta near 1; predictions in measured watts are not affected.\n")
        a("### 2.1 Fit and out-of-sample test\n")
        a(f"{W['windows']} windows ({W['window_hours']:.1f} h of start points, stride {cfg['window_stride'] * cfg['grid']} s). Held-out unit is a local calendar day; training excludes any window within 30 min of the held-out day. Persistence = last water value held. **Known power** feeds the measured CPU and GPU power over the whole horizon into the model, which a planner cannot have. **Frozen power** holds the power of the last 30 s before the decision constant over the horizon (fan and pump follow the measured trajectory, i.e. the plan).\n")
        rows = []
        for fo in W["cv"]["folds"]:
            rows.append([fo["day"], fo["n_test"]] + [f"{fo['rmse_model'][h]:.2f} / {fo['rmse_persist'][h]:.2f}" for h in fo["rmse_model"]])
        rows.append(["pooled", sum(fo["n_test"] for fo in W["cv"]["folds"])] + [f"{pooled[h]['rmse_model']:.2f} / {pooled[h]['rmse_persist']:.2f} ({100 * pooled[h]['skill']:.0f} %)" for h in pooled])
        a(tab(["Held-out day (days since epoch)", "windows", "5 min RMSE model / persistence K (known power)", "15 min", "30 min"], rows))
        a("\nFrozen-power forecast, leave-one-day-out, same windows (K):\n")
        rows = [[h, f"{v['rmse_known']:.2f}", f"{v['rmse_frozen']:.2f}", f"{v['rmse_persist']:.2f}", f"{100 * v['skill_known']:.0f} %", f"{100 * v['skill_frozen']:.0f} %", f"{v['p95_under']:.1f}", f"{v['p99_under']:.1f}", f"{v['max_under']:.1f}", f"{v['two_sigma']:.1f}"] for h, v in fz.items()]
        a(tab(["horizon s", "RMSE known power", "RMSE frozen power", "RMSE persistence", "skill known", "skill frozen", "p95 under-prediction", "p99 under-prediction", "max under-prediction", "2 sigma frozen"], rows))
        a(f"\nThe headline skill is the frozen-power one: it is negative at every horizon ({100 * fz['300']['skill_frozen']:.0f} % at 5 min, {100 * fz['900']['skill_frozen']:.0f} % at 15 min), which agrees with `docs/model.md` (no model beats persistence significantly at 5 or 15 min). The known-power skill of {100 * pooled['300']['skill']:.0f} to {100 * pooled['1800']['skill']:.0f} % measures the plant response given the load, not forecasting. Fitting on all data instead of leaving a day out changes the frozen RMSE by at most 0.01 K (`global_fit` in `res_ext.json`). Under-prediction means the water ended warmer than the model said; the margin to plan against is therefore 2 sigma of {fz['240']['two_sigma']:.1f} to {fz['480']['two_sigma']:.1f} K for 4 to 8 min, and the p99 is {fz['240']['p99_under']:.1f} to {fz['480']['p99_under']:.1f} K.\n")
        pr = B["params"]
        a("### 2.2 Parameters with block-bootstrap intervals (95 %, median)\n")
        a(tab(["Parameter", "Point fit", "Bootstrap median [2.5, 97.5]", "Note"], [
            ["C [J/K]", f"{x['C']:.0f}", self.ci(pr["C"], 0), f"total heat capacity; {min(s['x'][0] for s in W['sensitivity']) / 1000:.1f} to {max(s['x'][0] for s in W['sensitivity']) / 1000:.1f} kJ/K across the structural variants below; split into two lumps in 3.2"],
            ["eta_cpu", f"{x['eta_cpu']:.2f}", self.ci(pr["eta_cpu"], 2), "package power to water"],
            ["eta_gpu", f"{x['eta_gpu']:.2f}", self.ci(pr["eta_gpu"], 2), "at the cap 1.0"],
            ["Gn [W/K]", f"{x['Gn']:.2f}", self.ci(pr["Gn"], 2), "fan-independent part, at its lower bound 0"],
            ["A [W/K]", f"{x['A']:.1f}", self.ci(pr["A"], 1), "fan part at full rpm, pump 100 %"],
            ["m", f"{x['m']:.2f}", self.ci(pr["m"], 2), "weakly identified, see 4.2"],
            ["gamma", f"{x['gamma']:.2f}", self.ci(pr["gamma"], 2), "pump coefficient; confounded with water temperature and day (4.1), not interpreted physically"],
            ["Ta [C]", f"{x['Ta']:.1f}", self.ci(pr["Ta"], 1), "effective sink temperature, includes any constant extra heat"],
        ]))
        a(f"\nDerived: G at full fan, pump 100 % = {self.ci(B['G_full_pump100'])} W/K; pump about 20 % = {self.ci(B['G_full_pump20'])} W/K; ratio {self.ci(B['G_ratio_pump20_over_100'], 3)}. Bootstrap: {B['draws']} draws, {B['how']}.\n")
        a("### 2.3 Sensitivity of the structure (all refit, pooled known-power skill at 5 / 15 / 30 min)\n")
        a(tab(["Variant", "SSE", "C kJ/K", "G full fan (pump 100) W/K", "m", "Ta", "P0 W", "skill"], [[s["tag"], f"{s['cost']:.0f}", f"{s['x'][0] / 1000:.2f}", f"{s['x'][3] + s['x'][4]:.1f}", f"{s['x'][5]:.2f}", f"{s['x'][7]:.1f}", f"{s['x'][8]:.0f}", " / ".join(f"{s['skill'][h]:.3f}" for h in s["skill"])] for s in W["sensitivity"]]))
        a(f"\nC and G at full fan do not depend on the unknown ambient: they are pinned by 35 h at full fan with pump 100 % and 10 h with pump about 20 %. Ambient, extra constant heat P0 and the fan exponent m trade almost freely (SSE changes by 2 % between Ta = 20 and 25 C, and the Ta 20 / P0 {W['sensitivity'][1]['x'][8]:.0f} W fit has a lower SSE, {W['sensitivity'][1]['cost']:.0f}, than the base {W['cost']:.0f}). `alt_curve` in `res_water.json` is the variant `{W['alt_curve']['tag']}` (Ta {E['checks']['alt_ta']:.0f} C, P0 {E['checks']['alt_p0']:.0f} W) and was checked to equal that row of the table: {E['checks']['alt_curve_matches_sensitivity']}. The settings below use the base curve and this alternative side by side.\n")
        a("### 2.4 Physical plausibility\n")
        ph = self.PH["assumptions"]
        a(f"- C against an estimate (ESTIMATE, my assumptions): coolant {ph['coolant_l'][0]} to {ph['coolant_l'][1]} L at {ph['coolant_kj_per_l_k'][0]} to {ph['coolant_kj_per_l_k'][1]} kJ/(L K), three radiators at {ph['rad_metal_kj_per_k_each'][0]} to {ph['rad_metal_kj_per_k_each'][1]} kJ/K metal each, blocks, pump and fittings {ph['blocks_pump_fittings_kj_per_k'][0]} to {ph['blocks_pump_fittings_kj_per_k'][1]} kJ/K: {self.PH['estimate_kj_per_k'][0]:.1f} to {self.PH['estimate_kj_per_k'][1]:.1f} kJ/K. The fitted {self.PH['fitted_kj_per_k']:.1f} kJ/K lies inside; this check is weak because the range is wide.")
        a(f"- Heat share: eta_cpu = {x['eta_cpu']:.2f} is physical. eta_gpu is pushed to the cap 1.0 (unconstrained it goes to 1.1); fixing it lower costs SSE {next(v for v in W['sensitivity'] if v['tag'] == 'eta_gpu fixed 0.8')['cost']:.0f} at 0.8 and {next(v for v in W['sensitivity'] if v['tag'] == 'eta_gpu fixed 0.9')['cost']:.0f} at 0.9 against {W['cost']:.0f}, so the GPU block delivers at least about 0.9 of the NVML board power. CPU and GPU heat shares agree at a ratio of 0.98 [0.86, 1.10] in the review's slope-corrected 10 min blocks (weakly resolved).")
        a(f"- G at full fan about 24 W/K for three 360 radiators is the right order (ESTIMATE of a typical 360 radiator at full fan: 6 to 10 W/K each).\n")
        a("### 2.5 G at states with data, tau = C/G\n")
        rows = []
        for rw in T["binned"]["base"]:
            lo, hi = T["binned"]["Ta20_P0free"], T["binned"]["Ta27_P0free"]
            sel = lambda tb: next(q for q in tb if q["pump"] == rw["pump"] and q["fan_lo"] == rw["fan_lo"])
            enough = rw["hours"] >= 2.0 and (rw["G_hi"] - rw["G_lo"]) / 2 / rw["G"] <= 0.25
            rows.append([rw["pump"], f"{rw['fan_mean_rpm']:.0f}", rw["blocks"], f"{rw['hours']:.1f}", f"{rw['tw_p5']:.1f} to {rw['tw_p95']:.1f}", f"{rw['G']:.1f} [{rw['G_lo']:.1f}, {rw['G_hi']:.1f}]", f"{sel(lo)['G']:.1f} / {sel(hi)['G']:.1f}", f"{x['C'] / rw['G']:.0f}", "yes" if enough else "NO: thin"])
        a(tab(["Pump", "Fan rpm", "5 min blocks", "hours", "Tw span C", "G W/K (Ta 25) [95 %]", "G at Ta 20 / 27", "tau s", "Enough data"], rows))
        a("\nBlock method: G = sum(Q_eff (Tw-Ta)) / sum((Tw-Ta)^2) over 5 min blocks with Q_eff = heat - C dTw/dt; the interval is a 3 h block bootstrap (it does not contain the ambient uncertainty, shown in the Ta 20 / 27 column). Only the two full-fan states have enough data; the sub-full states appear for under 2 h each and all at one water temperature.\n")
        a("### 2.6 Heating rate in the water (K/min), heat entering the water, fan stopped\n")
        rows = []
        for q in self.cfg["ext"]["restart"]["rates_q_w"]:
            l1, l2 = self.rate("lump1", q, 0.5), self.rate("lump2", q, 0.5)
            l1h, l2h = self.rate("lump1", q, 5.0), self.rate("lump2", q, 5.0)
            rows.append([f"{q:.0f}", f"{l1['avg_k_min_4min']:.2f} to {l1h['avg_k_min_4min']:.2f}", f"{l2['k_min_at_t0']:.2f}", f"{l2['k_min_at_60s']:.2f} to {l2h['k_min_at_60s']:.2f}", f"{l2['avg_k_min_4min']:.2f} to {l2h['avg_k_min_4min']:.2f}"])
        a(tab(["Heat W", "one lump, 4 min mean (G_stop 0.5 to 5)", "two lumps, at the start", "two lumps, at 60 s", "two lumps, 4 min mean"], rows))
        a(f"\nTwo lumps are the model of 3.2. Fan stopped: natural-convection G was never observed (lowest rpm seen {self.T['exposure']['fan_min_rpm']:.0f}, for seconds); the range uses G_stop = {self.P['gs_lo']} to {self.P['gs_hi']} W/K, ESTIMATE from physics, and is applied only at rpm 0 (earlier versions applied it at every rpm). The stopped-fan rate is insensitive to this bound at 400 W (within 15 %). Full fan, pump at the floor, Tw 33 C / 40 C, one lump: " + ", ".join(f"{h['q_w']:.0f} W {h['full_fan_pump_floor']:+.2f}" for h in base["heating"] if h["tw"] == 33.0) + " K/min.\n")

    def dynamics(self):
        a, tab, D, S, E, B = self.a, self.tab, self.D, self.S, self.E, self.B
        ef, ev = E["events"]["fit"], E["events"]
        a("## 3. Dead time and time constants\n")
        a("### 3.1 Power step to CPU die, GPU die, water\n")
        rows = []
        for k, v in D["die"].items():
            rows.append([k, f"{v['R_total']:.3f}", f"{v['dead_s']:.1f}", f"{v['tau1']:.1f}", f"{v['t63_s']:.0f}", f"{v['t90_s']:.0f}", f"{v['r2']:.2f}"])
        a(tab(["Sensor", "K per W (above water)", "dead time s", "fast tau s", "63 % reached s", "90 % reached s", "R2"], rows))
        a("\nThe die responds within the 1 s sampling; dead time and tau here are upper bounds of about 1 to 2 s. Core Max carries spike noise. CPU gain 0.18 to 0.20 K/W: 250 W adds about 45 to 50 K above water. GPU 0.06 K/W: even 320 W adds 20 K. Die temperatures carry almost no information about the water, which is why they never trigger anything.\n")
        a("Water kernel (ridge FIR from CPU and GPU power to the 10 s change of Tw):\n")
        rows = []
        for lab, k in (("pump 100 %", "kernel_pump100"), ("pump about 20 %", "kernel_pump20")):
            for src in ("cpu", "gpu"):
                v = D[k][src]
                rows.append([lab, src, D[k]["n"], f"{v['onset_s']:.1f}", f"{v['peak_lag_s']:.1f}", f"{v['centroid_s']:.1f}", f"{v['C_over_eta_kj_per_k']:.1f}"])
        a(tab(["Pump", "source", "rows", "onset s", "peak lag s", "centroid s", "C/eta kJ/K from kernel area"], rows))
        a(f"\nDead time (centroid of the heat arrival) is {S['dead_s']['100']:.0f} s at pump 100 % and {S['dead_s']['20']:.0f} s at about 20 %; ESTIMATE {S['dead_s']['floor_est']:.0f} s at the 15 % floor (roughly 1/flow). The earlier statement that the response starts within 2.5 s at pump 100 % is wrong: event-locked, the rise is {ev['p100']['lags']['10']['obs']:.3f} +- {ev['p100']['lags']['10']['se']:.3f} K per 100 W at 10 s and the onset is at about {ev['p100']['onset_s']:.0f} s (pump 20 %: {ev['p20']['onset_s']:.0f} s).\n")
        a("### 3.2 Event-locked steps and the two-lump model\n")
        a(f"Method: {ev['n_found']} power steps of at least 70 W in CPU + GPU + pump power with the fan at full speed throughout, calm 150 s before and after (steps smaller than 35 % of their size in noise), split by pump state: {ev['n']['p100']} at pump 100 % ({ev['p100']['up']} up) and {ev['n']['p20']} at pump about 20 % ({ev['p20']['up']} up), mean size {ev['p100']['mean_abs_dq_w']:.0f} / {ev['p20']['mean_abs_dq_w']:.0f} W. Each response is the water rise after the pre-step trend, normalised to 100 W; the table gives the mean over events at several lags (se = standard error over events) against the fitted one-lump (C = {self.x['C'] / 1000:.1f} kJ/K, dead time from 3.1) and two-lump models.\n")
        rows = []
        for pc, lab in (("p100", "pump 100 %"), ("p20", "pump 20 %")):
            for s in ("30", "60", "120", "240"):
                v = ev[pc]["lags"][s]
                rows.append([lab, s, f"{v['obs']:.3f} +- {v['se']:.3f}", f"{v['lump1']:.3f}", f"{v['lump2']:.3f}"])
        a(tab(["Pump", "lag s", "observed K per 100 W", "one lump", "two lumps"], rows))
        a("")
        rows = []
        for pc, lab in (("p100", "pump 100 %"), ("p20", "pump 20 %")):
            for w, v in ev[pc]["windows"].items():
                rows.append([lab, w, f"{v['k_min_100w_obs']:.2f}", f"{v['k_min_100w_lump1']:.2f}", f"{v['k_min_100w_lump2']:.2f}", self.f(v["c_eff_obs_kj"]), self.f(v["c_eff_lump1_kj"]), self.f(v["c_eff_lump2_kj"])])
        a(tab(["Pump", "window s after step", "K/min per 100 W observed", "one lump", "two lumps", "C_eff observed kJ/K", "one lump", "two lumps"], rows))
        a("\nC_eff = (heat - G x temperature rise) / change of slope over the window, with the heat delayed by the dead time; in the 240 to 480 s window the slope change is within noise of the loss term and C_eff is not meaningful at pump 100 %.\n")
        fv = ev["fit_variants"]
        a(f"\nTwo-lump fit (heat enters lump 1 with the sensor, K couples to lump 2, total C held at {self.x['C'] / 1000:.1f} kJ/K, both pump states fitted together with their own delays, residuals weighted by the standard error): C1 = {ef['C1'] / 1000:.1f} kJ/K [{ef['boot_ci']['C1'][0] / 1000:.1f}, {ef['boot_ci']['C1'][1] / 1000:.1f}] ({ef['boot_n']} event-bootstrap draws), C2 = {ef['C2'] / 1000:.1f} kJ/K, K = {ef['K']:.0f} W/K [{ef['boot_ci']['K'][0]:.0f}, {ef['boot_ci']['K'][1]:.0f}], fast tau = C1 C2 / ((C1 + C2) K) = {ef['tau_fast_s']:.0f} s [{ef['boot_ci']['tau_fast_s'][0]:.0f}, {ef['boot_ci']['tau_fast_s'][1]:.0f}], fitted delays {ef['delay_s']['p100']:.0f} / {ef['delay_s']['p20']:.0f} s (pump 100 / 20 %). Unweighted fits and single-pump fits give C1 {fv['fixed']['C1'] / 1000:.1f} / {fv['p100']['C1'] / 1000:.1f} / {fv['p20']['C1'] / 1000:.1f} kJ/K and fast tau {fv['fixed']['tau_fast_s']:.0f} / {fv['p100']['tau_fast_s']:.0f} / {fv['p20']['tau_fast_s']:.0f} s (unweighted / pump 100 only / pump 20 only), so C1 is {min(fv['fixed']['C1'], fv['p100']['C1'], fv['p20']['C1'], ef['C1']) / 1000:.1f} to {max(fv['fixed']['C1'], fv['p100']['C1'], fv['p20']['C1'], ef['C1']) / 1000:.1f} kJ/K and the fast tau 38 to 115 s: not sharply resolved, the review gets C1 6 to 8 kJ/K, tau 49 to 67 s. The C total over 10 min or more is still {self.x['C'] / 1000:.1f} kJ/K ({self.ci(B['params']['C'], 0)} J/K); letting the data fix the total as well in the same 600 s responses gives {ev['fit_free_total']['C_total'] / 1000:.0f} kJ/K, i.e. 10 min cannot pin it.\n")
        l2 = E["lump2"]
        a(f"Cross-check on the 30 min windows (delays 0, 5, 10 s at pump 100 %, +20 s at pump 20 %; three subsets): the two-lump window fit lowers the SSE by only {100 * (1 - min(v['sse'] / v['sse_1lump'] for v in l2['variants'] if v['subset'] == 'all')):.0f} % and prefers a slow second lump (C1 {l2['range']['C1'][0] / 1000:.1f} to {l2['range']['C1'][1] / 1000:.1f} kJ/K, K {l2['range']['K'][0]:.0f} to {l2['range']['K'][1]:.0f} W/K, total {l2['range']['C_total'][0] / 1000:.1f} to {l2['range']['C_total'][1] / 1000:.1f} kJ/K): 30 min output error is insensitive to the first minutes, so the fast split rests on the events alone. The planner is mostly sensitive to those first minutes, so the split is used for every short-term number in this document, with 'C/2' as bounding case.\n")
        a("### 3.3 How much water follows a CPU spike (+power over the baseline, fan full, pump 100 %)\n")
        sp2 = {(s["extra_w"], s["duration_s"]): s for s in E["spikes2"]}
        a(tab(["Extra CPU W", "duration", "heat kJ into water", "peak rise K, one lump", "peak rise K, two lumps", "sensor steps (0.01 K), two lumps", "time of peak after start s (one lump)"], [[f"{s['extra_w']:.0f}", f"{s['duration_s']} s" if s["duration_s"] < 120 else f"{s['duration_s'] // 60} min", f"{s['energy_kj']:.1f}", f"{s['peak_rise_k']:.2f}", f"{sp2[(s['extra_w'], s['duration_s'])]['peak_lump2_k']:.2f}", f"{sp2[(s['extra_w'], s['duration_s'])]['peak_lump2_k'] / 0.01:.0f}", s["t_peak_s"]] for s in D["spikes"]]))
        a("\nThe rise is the energy divided by the capacity that responds (C1 for spikes up to about 2 min, C beyond), plus a little loss; it begins after the dead time. A 5 s spike is 4 to 13 sensor steps next to 0.005 K noise of a minute.\n")
        sk = D["soak"]
        a("### 3.4 Heat soak after load ends\n")
        a(f"{sk['n']} events (10 min earlier mean {sk['pre_load_w']:.0f} W CPU+GPU falling to {sk['post_load_w']:.0f} W). Mean water change after the drop (observed / one-lump model, K): " + ", ".join(f"{t}s {sk['obs_rise'][t]:+.2f}/{sk['model_rise'][t]:+.2f}" for t in ("30", "60", "120", "300", "600")) + f". Observed minus model is {sk['obs_minus_model']['120']:+.2f} K at 120 s (event SD {sk['obs_minus_model_sd']['120']:.2f}, SE about {sk['obs_minus_model_sd']['120'] / np.sqrt(sk['n']):.2f}): systematic, and the sign a fast lump gives (the water cools slightly further than one lump predicts). Beyond that there is no continued rise after the drop (largest observed rise {sk['max_obs_rise_after_drop']:.2f} K, the transit only), so no heat is stored that would warm the water later. Fans-off C may be higher, because the metal then follows the water; this cannot be observed.\n")

    def identification(self):
        a, tab, T, B, S, E, x, W = self.a, self.tab, self.T, self.B, self.S, self.E, self.x, self.W
        base, alt = S["base"], S["alt"]
        pm = E["pump"]
        a("## 4. Fan and pump: what the data can and cannot identify\n")
        a("### 4.1 Pump: confounded with the water temperature\n")
        a(f"- Pump below 2800 rpm ran for {pm['floor']['hours']:.1f} h with a maximum water temperature of {pm['floor']['tw_max']:.2f} C: {pm['floor']['hours_above_35']:.2f} h above 35 C and {pm['floor']['hours_above_36']:.2f} h above 36 C. **The floor pump above 36 C has zero data**; everything from 36 to 50 C at the floor is extrapolated. The lowest pump speed seen is {pm['pump_rpm_min']:.0f} rpm ({pm['hours_below_2500']:.2f} h below 2500 rpm, {pm['hours_2500_2800']:.1f} h at 2500 to 2800): the 15 % floor (about 2400 rpm) has never run, the 20 % state is 2570 rpm.")
        a("- The firmware pump PID (set-point 35 C) sends the pump to about 4813 rpm above 35.5 C, so pump speed is confounded with water temperature and with the day. Hours per day by pump state:\n")
        a(tab(["Day", "hours", "pump 100 %", "pump about 20 %", "pump other", "pump >= 4813 rpm"], [[d["day"], f"{d['hours']:.1f}", f"{d['pump100_h']:.1f}", f"{d['pump20_h']:.1f}", f"{d['pump_mid_h']:.2f}", f"{d['pump_ge_4813_h']:.1f}"] for d in pm["days"]]))
        a("\nThe earlier statement that 11-04 is a pump-20 day is withdrawn: it is a mixed day (pump 100 % for the first hours and the firmware excursion, 20 % otherwise). Median pump rpm on 11-04 by water temperature:\n")
        a(tab(["Tw from C", "to C", "hours", "median pump rpm"], [[b["tw_lo"], b["tw_hi"], f"{b['hours']:.2f}", self.f(b["pump_median_rpm"], 0)] for b in pm["day_1104_by_tw"]]))
        a("\nSame-day pump changes (local time; the three at 15:35, 16:55 and 20:59 are small firmware excursions, not 100 to 20 % switches, and are listed with what is measured around them, +-5 s excluded):\n")
        a(tab(["Asked", "found at", "pump rpm before to after", "Tw before C", "Tw change within 30 s K", "heat before / after W"], [[r["asked_local"][5:16], r["t_local"], f"{r['pump_before']:.0f} to {r['pump_after']:.0f}", f"{r['tw_before']:.1f}", f"{r['d_tw_30s_k']:+.2f}", f"{self.f(r['q_before_w'], 0)} / {self.f(r['q_after_w'], 0)}"] for r in pm["ramps"]]))
        n1 = T["natural"]["pump_100_to_20"]
        a(f"\n- The 100 to 20 % switch at 07:35:31 has no pre-switch CPU power for 32 s, so G before and after cannot be compared; what is seen is a drop of the sensor reading of about 0.2 to 0.35 K within 30 s at about 300 W, which fits a sensor downstream of the radiators and may explain part of the 0.5 to 0.8 K lower intercept on pump-20 days. After the switch G is {n1['post']['G']:.1f} W/K at full fan.")
        a(f"- G at full fan: pump 100 % {self.ci(B['G_full_pump100'])}, pump about 20 % {self.ci(B['G_full_pump20'])} W/K; ratio {self.ci(B['G_ratio_pump20_over_100'], 3)}. No loss of cooling from the slow pump is detectable, and the sign (20 % slightly better) is not significant and not interpreted: it moves with the day and with the water-temperature range. The review's cross-regime test: the pump-100 fit predicts pump 20 % with RMSE 0.22 / 0.35 / 0.65 K and +0.4 K bias (conservative); the reverse gives 0.48 / 0.81 / 0.92 K with -0.75 K bias, so a pump-20-only G of 28 to 29 W/K cannot be trusted.\n")
        n1, n2 = T["natural"]["fan_setpoint_test_1"], T["natural"]["fan_setpoint_test_2_aquasuite_stopped"]
        a("### 4.2 Fan: below 1100 rpm is unidentified\n")
        a(f"- Fan set-point tests 2026-11-04 (rpm 1460 to {n1['post']['fan_rpm']:.0f}, duty 99.9 to {n1['post']['fan_duty']:.0f} %): energy balance over 90 to 145 s windows gives G {n1['pre']['G']:.1f} to {n1['post']['G']:.1f} W/K (ratio {n1['G_ratio_by_ta']['25.0']:.2f}) in test 1 and {n2['pre']['G']:.1f} to {n2['post']['G']:.1f} (ratio {n2['G_ratio_by_ta']['25.0']:.2f}) in test 2 (aquasuite stopped); the windows are shorter than dead time plus kernel settling twice over, so they disagree by more than they allow. A 14 % rpm drop costs between 17 % and 48 % of G; the base curve (m = {x['m']:.2f}) predicts {100 * (1 - 0.86 ** x['m']):.0f} %.")
        a(f"- Fan unsaturated at water 30 C (PID set-point): {self.T['exposure']['fan_below_0_7_hours']:.1f} h below 70 % rpm, all at one water temperature; that is the whole evidence for G at low rpm, and it cannot separate G from Ta and P0.")
        a(f"- Local heat balance per 60 s block below 1400 rpm (Q_eff = heat - C slope against the removal G (Tw - Ta) of each curve; the gap is Q_eff minus removal, W; C = 11.7 or 8 kJ/K):\n")
        rows = []
        for t in E["lowrpm"]["table"]:
            rows.append([f"{t['rpm_lo']}-{t['rpm_hi']}", t["blocks"], f"{t['tw']:.1f}", f"{t['slope_k_min']:+.2f}"] + [f"{t[c]['pred_removal_w']:.0f}: {t[c]['gap_w_c11']:+.0f} / {t[c]['gap_w_c8']:+.0f}" for c in ("base", "alt22", "alt20")])
        a(tab(["rpm", "blocks", "Tw C", "slope K/min", "base (Ta 25, P0 0): removal W: gap C 11.7 / C 8", "alt Ta 22, P0 73", "alt Ta 20, P0 119"], rows))
        lr = E["lowrpm"]["rates"][0]
        a(f"\nAt 650 rpm the base curve leaves a gap of {E['lowrpm']['table'][2]['base']['gap_w_c11']:+.0f} W with C = 11.7 kJ/K and {E['lowrpm']['table'][2]['base']['gap_w_c8']:+.0f} W with C = 8: with the smaller C the gap mostly closes, so these runs cannot separate the curves, nor P0 from C. At {lr['rpm']:.0f} rpm and {lr['q_w']:.0f} W of heat the water rose {lr['k_min']:.2f} K/min, which means C of at most {lr['c_upper_kj_if_no_removal']:.0f} kJ/K, or at least {lr['extra_heat_w_if_c11_7']:.0f} W of unobserved heat (P0), or an exchanger transient. So P0 = 0 is doubtful, and Ta 20 / P0 119 W fits as well as the base. **P0 and C are ambiguous below 1100 rpm.**")
        ns = E["near_stopped"]
        a(f"- The start duty 20 % ({ns['min_run_rpm']:.0f} rpm) acts as near-stopped: net removal at 30 C and the pump floor is {ns['net_w_at_30c']['base']:.0f} W (base) and {ns['net_w_at_30c']['alt22']:.0f} / {ns['net_w_at_30c']['alt20']:.0f} W (alt curves, after their P0); gross G (Tw - Ta) is {ns['gross_w_at_30c']['base']:.0f} / {ns['gross_w_at_30c']['alt22']:.0f} / {ns['gross_w_at_30c']['alt20']:.0f} W. At idle heat of 40 W or more it does not bring the water back to the stop temperature.")
        sm = [s for s in W["sensitivity"][:7]]
        a(f"- Fan curve with intervals (ratio of G to full fan, pump 100 %): at 80 % rpm {self.ci(B['G_ratio_fan_0_8'], 2)}, at 50 % {self.ci(B['G_ratio_fan_0_5'], 2)}, at 27 % (390 rpm) {self.ci(B['G_ratio_fan_0_27'], 2)}. The intervals cover sampling only; across the ambient / P0 variants m ranges from {min(s['x'][5] for s in sm):.2f} to {max(s['x'][5] for s in sm):.2f}, and G at 390 rpm and pump floor is {base['G']['min_run_pump_floor']:.1f} W/K (base) or {alt['G']['min_run_pump_floor']:.1f} W/K (alt), a factor of about 3.\n")
        a("### 4.3 What needs a step test\n")
        a("1. G below about 1100 rpm (the fan curve), needed for the stop and restart design and every fan setting below full speed.\n2. Natural-convection G with the fan stopped (bounded only by estimate).\n3. The pump effect (+-10 % cannot be resolved), at fan full and at the 15 % floor, which has never been run, and above 36 C.\n4. The sink temperature and the true heat-to-water share (they trade), and P0.\n5. The dead time at the 15 % pump floor.\n6. The first-minute capacity C1 with the fan stopped (the metal follows the water then).\n")
        self.steptest()

    def steptest(self):
        a, tab, ST, cfg, x = self.a, self.tab, self.ST, self.cfg, self.x
        t = cfg["steptest"]
        rows_all = ST["rows"]
        a("### 4.4 Shortest step test (designed, not run)\n")
        a(f"Not run, and not to be run without the owner at the computer: it needs fan and pump writes. Idea: hold the water near a fixed temperature with a matched load so that each fan level is measured at the same Tw, and fit the whole sequence at once. Load: a stable GPU burn plus CPU stress, {t['q_w']:.0f} W of heat in the water at full fan (about G x 12 K), scaled per fan level by G(level)/G(full) so that Tw stays between 34 and 40 C, with a half-load segment at full fan so that Ta and the load scale separate. The matched loads are:\n")
        pl = Plant(self.W["x"], self.m, cfg)
        g1 = pl.G(1460.0, t["pump_floor"])
        rows = []
        for fl in t["fan_levels"]:
            g = pl.G(fl * 1460.0, t["pump_floor"])
            qm = t["q_w"] * g / g1
            rows.append([f"{100 * fl:.0f} % ({fl * 1460:.0f} rpm)", f"{g:.1f}", f"{qm:.0f}", f"{self.x['Ta'] + qm / g:.1f}"])
        a(tab(["Fan level", "G W/K (base curve, pump floor)", "matched load W", "steady Tw at that load C"], rows))
        a("\nThe lowest level asks for less heat than the idle machine produces (idle CPU 15 to 60 W, GPU 10 W, pump 4 W): there the load is the idle floor, and the water drifts up; the abort rule below bounds this.\n")
        modes = t["modes"]
        a(f"Duration from the numbers: the dead time is {self.S['dead_s']['floor_est']:.0f} s and the fast lump settles with a fast tau of {self.E['lump']['tau_fast_s']:.0f} s; the slow tau is {x['C'] / g1:.0f} s. The earlier design (hold 180 s, fit without the dead time) is refuted by the Monte-Carlo below: with a dead time of {t['delay_s']} s in the truth and none in the fit, G ratios are biased by tens of percent. Four fit situations: `lump_ignore` = one-lump truth, fit without dead time (the earlier analysis); `lump_fit` = one-lump truth, dead time in the fit; `two_fit` = two-lump truth (the fitted lumps of 3.2), dead time in the fit; `two_fit_off10` = as `two_fit` with the fitted dead time 10 s too short. {t['reps']} noisy repetitions each (sensor noise {t['noise']['t_sd']} K, load noise {t['noise']['q_sd']:.0f} W, 5 % load-scale error for the bias columns).\n")
        rows = []
        for kind, lab in (("fan", "fan, matched load"), ("pump", "pump ABAB")):
            for rr in rows_all:
                if rr["kind"] != kind:
                    continue
                rows.append([lab, rr["mode"], rr["hold_s"], f"{rr['total_s'] / 60:.0f} min", f"{100 * max(rr['G_ratio_rel_sd']):.1f} %", f"{100 * max(abs(v) for v in rr['G_ratio_rel_bias']):.1f} %", f"{100 * max(abs(v) for v in rr['G_ratio_rel_bias_with_q_bias']):.1f} %", f"{100 * rr['C_rel_bias']:+.0f} %"])
        cl = [rr for rr in rows_all if rr["kind"] == "fan_const_load"][0]
        rows.append(["fan, constant load (rejected)", cl["mode"], cl["hold_s"], f"{cl['total_s'] / 60:.0f} min", f"{100 * max(cl['G_ratio_rel_sd']):.1f} %", f"{100 * max(abs(v) for v in cl['G_ratio_rel_bias']):.1f} %", f"{100 * max(abs(v) for v in cl['G_ratio_rel_bias_with_q_bias']):.1f} %", f"{100 * cl['C_rel_bias']:+.0f} %"])
        a(tab(["Protocol", "fit situation", "hold s", "total", "worst G-ratio sd", "worst G-ratio bias", "bias with 5 % load error", "C bias"], rows))
        tol = t["pick_tol"] + 0.02
        def pick(kind, floor):
            for h in t["holds"]:
                if h < floor:
                    continue
                rr = [r for r in rows_all if r["kind"] == kind and r["hold_s"] == h and r["mode"] in ("lump_fit", "two_fit")]
                if all(max(abs(v) for v in r["G_ratio_rel_bias_with_q_bias"]) <= tol and max(r["G_ratio_rel_sd"]) <= tol for r in rr):
                    return h
            return t["holds"][-1]
        hf, hp = pick("fan", 180), pick("pump", 180)
        tf = next(r for r in rows_all if r["kind"] == "fan" and r["hold_s"] == hf and r["mode"] == "two_fit")["total_s"]
        tp = next(r for r in rows_all if r["kind"] == "pump" and r["hold_s"] == hp and r["mode"] == "two_fit")["total_s"]
        self.step_len = (tf + tp) / 60
        a(f"\n**Chosen:** fan test with hold {hf} s ({tf / 60:.0f} min including the 5 min lead and the two full-fan segments) plus pump test with hold {hp} s ({tp / 60:.0f} min), **{(tf + tp) / 60:.0f} min** in one session plus about 15 min cool-down; the dead time must be in the fit (or hold at least 360 s: ratio bias {100 * max(abs(v) for v in next(r for r in rows_all if r['kind'] == 'fan' and r['hold_s'] == 360 and r['mode'] == 'lump_fit')['G_ratio_rel_bias_with_q_bias']):.1f} % one-lump, {100 * max(abs(v) for v in next(r for r in rows_all if r['kind'] == 'fan' and r['hold_s'] == 360 and r['mode'] == 'two_fit')['G_ratio_rel_bias_with_q_bias']):.1f} % two-lump truth). Precision to claim: G ratios to about {100 * max(max(r['G_ratio_rel_sd']) for r in rows_all if r['kind'] == 'fan' and r['hold_s'] == hf and r['mode'] in ('lump_fit', 'two_fit')):.1f} % noise plus a bias of up to {100 * max(max(abs(v) for v in r['G_ratio_rel_bias_with_q_bias']) for r in rows_all if r['kind'] == 'fan' and r['hold_s'] == hf and r['mode'] in ('lump_fit', 'two_fit')):.0f} % from the lump structure, up to {100 * max(max(abs(v) for v in r['G_ratio_rel_bias_with_q_bias']) for r in rows_all if r['kind'] == 'fan' and r['hold_s'] == hf and r['mode'] == 'two_fit_off10'):.0f} % if the dead time is 10 s off; the pump ratio {100 * max(max(abs(v) for v in r['G_ratio_rel_bias_with_q_bias']) for r in rows_all if r['kind'] == 'pump' and r['hold_s'] == hp and r['mode'] in ('lump_fit', 'two_fit')):.1f} %. The earlier claim of under 1 % does not hold. Absolute G is biased (pump test about 17 %, fan test up to {100 * max(max(abs(v) for v in r['G_rel_bias']) for r in rows_all if r['kind'] == 'fan' and r['hold_s'] == hf and r['mode'] in ('lump_fit', 'two_fit')):.0f} %) because the sink Ta is free in the fit and trades with G; only ratios and C are claimed. A constant-load fan test is rejected: the load-scale error biases the ratios by {100 * max(abs(v) for v in cl['G_ratio_rel_bias_with_q_bias']):.0f} %.\n")
        a("Sequence (levels in % of full rpm, pump at the 15 % floor unless stated):\n")
        a(f"1. Fan test: 5 min lead at full fan with the full load; then {', '.join(f'{100 * v:.0f} %' for v in t['fan_levels'])} for {hf} s each with the matched load; 5 min full fan at the full load; 5 min full fan at half load. {tf / 60:.0f} min.\n2. Pump test (fan full, full load): 5 min lead at the floor, then pump 100 %, floor, 100 %, floor for {hp} s each. {tp / 60:.0f} min.\n3. Optional, +8 min: fan stopped at idle load from about 30 C, to see the stopped-fan G (slope of 0.2 to 0.4 K/min at 5 K above Ta; resolves G_stop to about +-0.5 W/K).\n")
        a("Abort rules (any one): Tw >= 44 C (2 K under the plan limit; the fan returns to 100 % and the pump to 100 % at once); Tw rising faster than 1.5 K/min at a level; CPU or GPU die within 5 K of its own limit; telemetry gap over 10 s; owner leaves the computer.\n")
        a("Identifies: G(rpm) at 27, 40, 55, 75 and 100 % as ratios to full fan (shape of the fan curve and m), the pump 15 % versus 100 % effect on G at full fan, Ta (sink) and the load scale from the half-load segment, the fitted dead time at the floor, and the total C (bias {:.0f} to {:.0f} %); the first-minute C1 only through the added stopped-fan segment.\n".format(100 * min(r["C_rel_bias"] for r in rows_all if r["kind"] == "fan" and r["hold_s"] == hf and r["mode"] in ("lump_fit", "two_fit")), 100 * max(r["C_rel_bias"] for r in rows_all if r["kind"] == "fan" and r["hold_s"] == hf and r["mode"] in ("lump_fit", "two_fit"))))
        a("### 4.5 Sensor quality and fan response\n")
        D, E = self.D, self.E
        se = D["sensor"]
        sp = E["spool"]
        a(f"- Resolution: {se['lsb_k']} K per step. {100 * se['zero_step_fraction']:.0f} % of consecutive 1 s samples are unchanged and {100 * se['one_lsb_fraction']:.0f} % differ by exactly one step. Smallest resolvable rate: {se['min_resolvable_rate_k_per_min_over_30s']:.2f} K/min over 30 s, {se['min_resolvable_rate_k_per_min_over_120s']:.3f} K/min over 120 s.\n- Noise on quiet minutes ({se['quiet_blocks']} blocks): residual SD about a straight line {1000 * se['noise_sd_k']['median']:.1f} mK median; quantisation alone would be {1000 * se['quantization_sd_k']:.1f} mK, so the sensor is quantisation limited.\n- Two paths to the same sensor (D5 report and LHM): difference {1000 * se['lhm_vs_d5']['mean_k']:.1f} mK mean, SD {1000 * se['lhm_vs_d5']['sd_k']:.0f} mK, step correlation {se['lhm_vs_d5_xcorr_of_steps']['0']:.2f} at lag 0.\n- Lag of the sensor against the true water is not separable from transit (3.1).")
        a(f"- Fan spool: on {sp['n']} duty jumps the rpm reaches 63 % after {sp['all']['t63_med_s']:.0f} s (p90 {sp['all']['t63_p90_s']:.0f} s) and 90 % after {sp['all']['t90_med_s']:.0f} s (p90 {sp['all']['t90_p90_s']:.0f} s), i.e. t63 4 to 5 s, t90 8 to 12 s; the earlier 'below 1 s' came from a grid minimum on data that is 86 % saturated. Spin-up from standstill was never observed: the lowest rpm seen is {sp['lowest_rpm_seen']:.0f} (held at 144 rpm on 5.2 % duty), and every jump above started from {sp['all']['min_start_rpm']:.0f} rpm or more. The model uses a first-order spool of {self.P['spool_s']} s. One tach for nine fans: 8 of 9 are unobserved. Static map duty to rpm: " + ", ".join(f"{m[0]:.0f} % = {m[1]:.0f}" for m in D["fan"]["static_map"][::2]) + ".")
        a("- Fan to sensor delay was not measured separately: 'invisible for the dead time' is the model, with one favourable observation (test 1 turned downward within 15 s of the fan restore, n = 1).\n")

    def capacity(self):
        a, tab, E, S, x = self.a, self.tab, self.E, self.S, self.x
