        g_move = lambda q: abs(next(r for r in E["restart"]["daemon"] if r["q_w"] == q and r["gs"] == 5.0 and r["model"] == "lump2" and r["variant"] == "nominal")["t_35_s"] - next(r for r in E["restart"]["daemon"] if r["q_w"] == q and r["gs"] == 0.5 and r["model"] == "lump2" and r["variant"] == "nominal")["t_35_s"])
        g23 = {r["sink_c"]: r for r in self.sink_rows() if r["g_label"].startswith("G 23.8")}
        a("## 7. Final settings table\n")
